<div class="page-heading"><p class="eyebrow">Development-ready importer</p><h1>CSV Import</h1><p>Validate documentation rows before they are written to the knowledge base.</p></div><?php require base_path('views/admin/_nav.php'); ?><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><?php if($failures):?><div class="alert alert-warning"><strong>Import failures</strong><ul class="mb-0"><?php foreach($failures as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><section class="panel import-panel"><div><h2>Upload source</h2><p>Maximum 2 MB and 500 rows. New systems, categories, and carriers are created as needed.</p><form method="post" enctype="multipart/form-data" data-loading-form><?=csrf_field()?><input type="hidden" name="action" value="preview"><label class="form-label">CSV file</label><input class="form-control" type="file" name="csv" accept=".csv,text/csv" required><button class="btn btn-primary mt-3" data-loading-text="Validating..."><span>Validate and preview</span></button></form></div><div class="csv-format"><h2>Required columns</h2><code>title, system, category, carrier, error_code, error_message, cause, resolution, keywords</code><h2>Optional columns</h2><code>type, severity, status</code><p>Optional values default to Article, Low, and Draft.</p></div></section><?php if($preview):?><section class="panel mt-3"><div class="panel-heading"><div><h2>Validated preview</h2><small><?=count($preview)?> row(s) ready</small></div><form method="post" data-loading-form><?=csrf_field()?><input type="hidden" name="action" value="import"><button class="btn btn-success" data-loading-text="Importing..."><span>Import <?=count($preview)?> row(s)</span></button></form></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Title</th><th>System</th><th>Carrier</th><th>Code</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($preview,0,50) as $row):?><tr><td><?=e($row['title'])?></td><td><?=e($row['system'])?></td><td><?=e($row['carrier'])?></td><td><code><?=e($row['error_code'])?></code></td><td><?=e($row['type']?:'Article')?></td><td><?=e($row['status']?:'Draft')?></td></tr><?php endforeach;?></tbody></table></div><?php if(count($preview)>50):?><p class="text-secondary small">Showing the first 50 validated rows.</p><?php endif;?></section><?php endif;?>
